mapper.select:
SELECT t.SOURCE_SYSTEM_ID, m.NAME AS MODEL_NAME, m.ID AS MODEL_ID, m.ICON, m.TYPE, m.PARENT_ID, m.CODE AS MODEL_CODE, m.DESCRIPTION, m.RESPONSIBLE_USER_ID, m.CREATOR_ID, m.CREATE_BY, m.CREATE_TIME, m.UPDATE_TIME, COALESCE(rv.VERSION_NO, v.VERSION_NO) AS VERSION_NO, v.STATUS AS VERSION_STATUS, (SELECT COUNT(*) FROM MERGE_DUPLICATE_TASK d WHERE d.MODEL_ID = m.ID AND d.DEL_FLAG = '0') AS DUPLICATE_TASK_COUNT, (SELECT COUNT(*) FROM QUALITY_TASK q WHERE q.MODEL_ID = m.ID AND q.DEL_FLAG = '0') AS QUALITY_TASK_COUNT FROM ( SELECT DISTINCT SOURCE_SYSTEM_ID, MODEL_ID FROM INGEST_TASK WHERE DEL_FLAG = '0' AND SOURCE_SYSTEM_ID IN
#{id}
) t INNER JOIN MODEL_BASE m ON m.ID = t.MODEL_ID AND m.DEL_FLAG = '0' LEFT JOIN MODEL_BASE parent ON parent.ID = m.PARENT_ID AND parent.DEL_FLAG = '0' LEFT JOIN MODEL_VERSION v ON v.ID = COALESCE(m.VERSION_ID, parent.VERSION_ID) AND v.DEL_FLAG = '0' LEFT JOIN MODEL_BASE published_model ON published_model.ID = CASE WHEN m.PARENT_ID IS NULL OR m.PARENT_ID = 0 THEN m.ID ELSE m.PARENT_ID END AND published_model.DEL_FLAG = '0' LEFT JOIN MODEL_INSTANCE published_instance ON published_instance.ID = published_model.PUBLISHED_INSTANCE_ID AND published_instance.MODEL_ID = published_model.ID AND published_instance.STATUS = 'SUCCEEDED' LEFT JOIN MODEL_VERSION rv ON rv.ID = published_instance.MODEL_VERSION_ID AND rv.MODEL_ID = published_model.ID AND rv.DEL_FLAG = '0' ORDER BY t.SOURCE_SYSTEM_ID, m.NAME

SELECT USER_ID
FROM SYSTEM_USER
WHERE DEL_FLAG = '0'
  AND (NICK_NAME LIKE #{keyword}
    OR USER_NAME LIKE #{keyword}
    OR PHONENUMBER LIKE #{keyword})
